import CoreML
import Foundation
import XCTest

@testable import OpenMedKit

/// Replays `tests/fixtures/parity/decision_encoder_v1.json`, generated by the
/// Python GLiClass ONNX reference path over a tiny random encoder, through the
/// Core ML encoder adapter and the on-device decision runtime.
final class DecisionRuntimeParityTests: XCTestCase {
    private func fixture() throws -> [String: AgentJSON] {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<5 { root.deleteLastPathComponent() }
        let data = try Data(contentsOf: root.appending(path: "tests/fixtures/parity/decision_encoder_v1.json"))
        guard case .object(let values) = try AgentJSON.parse(data) else {
            throw XCTSkip("fixture is not an object")
        }
        XCTAssertEqual(values["schema_version"], .string("openmed.tests.decision_encoder_parity.v1"))
        XCTAssertEqual(values["synthetic"], .boolean(true))
        XCTAssertEqual(values["decision_schema_version"], .string(OpenMedDecision.schemaVersion))
        return values
    }

    func testSharedVectorsMatchThePythonReferenceThroughCoreML() throws {
        let corpus = try fixture()
        let tokenizer = try WordLevelTokenizer(corpus["tokenizer"])
        let spec = try TinyEncoderSpec(corpus["encoder"])
        let tolerance = try object(corpus["tolerance"])
        let scoreTolerance = try XCTUnwrap(tolerance["scores"]?.decisionNumber)
        let logitTolerance = try XCTUnwrap(tolerance["logits"]?.decisionNumber)
        let backend = try object(corpus["backend"])
        let identity = try OpenMedDecisionBackendIdentity(
            backendID: string(backend["backend_id"]), runtime: string(backend["runtime"]),
            modelID: string(backend["model_id"]), revision: string(backend["revision"]),
            licenseID: string(backend["license_id"]))
        let runtimes = try object(corpus["runtimes"])
        let cases = try array(corpus["cases"])
        XCTAssertGreaterThanOrEqual(cases.count, 28)

        for entry in cases {
            let row = try object(entry)
            let id = try string(row["id"])
            let settings = try object(runtimes[try string(row["runtime"])])
            let model = TinyCoreMLModel(spec: spec, fault: settings["fault"].flatMap { try? string($0) })
            let runtime = try OpenMedEncoderDecisionRuntime(
                encoder: OpenMedCoreMLDecisionEncoder(model: model),
                tokenizer: tokenizer,
                identity: identity,
                configuration: configuration(settings),
                policy: policy(row["policy"]),
                calibrationProfiles: profiles(row["calibration_profiles"]))

            let result = try runtime.decide(json: XCTUnwrap(row["request"]).canonical())
            let expected = try object(row["expected"])
            assertClose(result.jsonValue, try XCTUnwrap(expected["result"]), tolerance: scoreTolerance, path: id)
            XCTAssertFalse(result.autonomousAction, id)
            XCTAssertTrue(result.reviewRequired, id)

            let calls = try array(expected["encoder_calls"])
            XCTAssertEqual(model.calls.count, calls.count, id)
            for (call, recorded) in zip(calls, model.calls) {
                let values = try object(call)
                XCTAssertEqual(values["input_ids"], .array(recorded.ids.map { .integer(Int64($0)) }), id)
                if let logits = values["logits"], logits != .null, let produced = recorded.logits {
                    assertClose(.array(produced.map(AgentJSON.number)), logits, tolerance: logitTolerance, path: id)
                }
            }
        }
    }

    func testInvalidRequestsFailWithTheSharedErrorKinds() throws {
        let corpus = try fixture()
        let rows = try array(corpus["invalid_requests"])
        XCTAssertGreaterThanOrEqual(rows.count, 25)
        for entry in rows {
            let row = try object(entry)
            let id = try string(row["id"])
            let data = try XCTUnwrap(row["request"]).canonical()
            XCTAssertThrowsError(try OpenMedDecisionRequest(json: data), id) { error in
                let decisionError = error as? OpenMedDecisionError
                XCTAssertEqual(decisionError?.kind, try? self.string(row["error"]), id)
            }
        }
    }

    func testErrorsAndDescriptionsAreValueFree() throws {
        let secret = "Synthetic secret patient phrase 4266"
        let invalid = Data("{\"mode\":\"fixed_choice\",\"input_text\":\"\(secret)\",\"options\":[\"\(secret)\"]}".utf8)
        XCTAssertThrowsError(try OpenMedDecisionRequest(json: invalid)) { error in
            XCTAssertFalse(String(describing: error).contains(secret))
            XCTAssertFalse(error.localizedDescription.contains(secret))
            XCTAssertEqual((error as? OpenMedDecisionError)?.reason, "options_invalid")
        }
        let request = try OpenMedDecisionRequest(mode: .booleanChoice, inputText: secret, options: ["yes", "no"])
        XCTAssertFalse(String(describing: request).contains(secret))
        XCTAssertFalse(String(reflecting: request).contains(secret))
        XCTAssertFalse(Mirror(reflecting: request).children.contains { "\($0.value)".contains(secret) })
        let example = try OpenMedGLiClassExample(text: secret, labels: ["yes"])
        let configuration = try OpenMedGLiClassConfiguration(prompt: secret, examples: [example])
        for value in [example as Any, configuration as Any] {
            var dumped = ""
            dump(value, to: &dumped)
            XCTAssertFalse(String(describing: value).contains(secret))
            XCTAssertFalse(String(reflecting: value).contains(secret))
            XCTAssertFalse(dumped.contains(secret))
        }
    }

    func testTimeoutsAreTypedFailures() throws {
        let corpus = try fixture()
        var now: TimeInterval = 0
        let runtime = try OpenMedEncoderDecisionRuntime(
            encoder: OpenMedCoreMLDecisionEncoder(model: TinyCoreMLModel(spec: TinyEncoderSpec(corpus["encoder"]), fault: nil)),
            tokenizer: WordLevelTokenizer(corpus["tokenizer"]),
            identity: OpenMedDecisionBackendIdentity(
                backendID: "openmed.tests.tiny", runtime: "coreml", modelID: "openmed/tiny", revision: "1.0.0",
                licenseID: "Apache-2.0"),
            clock: {
                now += 10
                return now
            })
        let request = try OpenMedDecisionRequest(
            mode: .fixedChoice, inputText: "Synthetic urgent note.", options: ["urgent", "routine"], timeoutMS: 100)
        let result = runtime.decide(request)
        XCTAssertEqual(result.state, .failure)
        XCTAssertEqual(result.code, "backend_timeout")
        XCTAssertTrue(result.optionScores.isEmpty)
        XCTAssertNil(result.choice)
    }

    func testCoreMLAdapterRejectsUnexpectedOutputs() throws {
        let corpus = try fixture()
        let spec = try TinyEncoderSpec(corpus["encoder"])
        let encoder = OpenMedCoreMLDecisionEncoder(model: TinyCoreMLModel(spec: spec, fault: "rank3"))
        XCTAssertThrowsError(try encoder.logits(inputIDs: [2, 4, 3], attentionMask: [1, 1, 1])) { error in
            XCTAssertEqual(error as? OpenMedDecisionEncoderError, .invalidOutput)
        }
        let renamed = OpenMedCoreMLDecisionEncoder(model: TinyCoreMLModel(spec: spec, fault: nil), logitsName: "scores")
        XCTAssertThrowsError(try renamed.logits(inputIDs: [2, 4, 3], attentionMask: [1, 1, 1])) { error in
            XCTAssertEqual(error as? OpenMedDecisionEncoderError, .missingOutput)
        }
        XCTAssertThrowsError(try encoder.logits(inputIDs: [2], attentionMask: [])) { error in
            XCTAssertEqual(error as? OpenMedDecisionEncoderError, .invalidInput)
        }
    }

    func testConfigurationIsValidated() throws {
        XCTAssertThrowsError(try OpenMedGLiClassConfiguration(prompt: "Decide <<SEP>> now."))
        XCTAssertThrowsError(try OpenMedGLiClassConfiguration(scoreLevels: ["low", "LOW"]))
        XCTAssertThrowsError(try OpenMedGLiClassConfiguration(maxLength: 0))
        XCTAssertThrowsError(
            try OpenMedDecisionBackendIdentity(
                backendID: "b", runtime: "coreml", modelID: "m", revision: "1.0.0", licenseID: "Apache-2.0",
                licenseSHA256: String(repeating: "a", count: 64)))
        XCTAssertThrowsError(try OpenMedDecisionAccessPolicy(allowedNamespaces: [], allowedPurposes: ["quality"]))
        XCTAssertThrowsError(
            try OpenMedDecisionCalibrationProfile(json: Data("{\"calibration_id\":\"x\"}".utf8)))
        let lenient = try OpenMedDecisionCalibrationProfile(
            calibrationID: "openmed.tests.profile", version: "1.0.0", method: "deterministic_margin",
            minimumConfidence: 0.5, minimumMargin: 0.1, multiLabelThreshold: 0.5,
            inDomainDigest: "sha256:" + String(repeating: "1", count: 64),
            outOfDomainDigest: "sha256:" + String(repeating: "2", count: 64))
        XCTAssertEqual(try OpenMedDecisionCalibrationProfile(json: lenient.jsonValue.canonical()), lenient)
        let prompted = try OpenMedGLiClassConfiguration(prompt: "Classify.")
        XCTAssertEqual(prompted.promptDigest?.count, 71)
        XCTAssertEqual(prompted.formatInput("Text.", labels: ["a", "b"]), "<<LABEL>>a<<LABEL>>b<<SEP>>Classify.Text.")
    }

    // MARK: - Fixture helpers

    private func object(_ value: AgentJSON?) throws -> [String: AgentJSON] {
        guard case .object(let values)? = value else { throw OpenMedDecisionError.invalidConfiguration(reason: "fixture") }
        return values
    }

    private func array(_ value: AgentJSON?) throws -> [AgentJSON] {
        guard case .array(let values)? = value else { throw OpenMedDecisionError.invalidConfiguration(reason: "fixture") }
        return values
    }

    private func string(_ value: AgentJSON?) throws -> String {
        guard case .string(let text)? = value else { throw OpenMedDecisionError.invalidConfiguration(reason: "fixture") }
        return text
    }

    private func configuration(_ settings: [String: AgentJSON]) throws -> OpenMedGLiClassConfiguration {
        let examples = try array(settings["examples"]).map { item -> OpenMedGLiClassExample in
            let example = try object(item)
            return try OpenMedGLiClassExample(
                text: string(example["text"]), labels: array(example["labels"]).map { try string($0) })
        }
        guard case .integer(let maxLength)? = settings["max_length"], case .boolean(let promptFirst)? = settings["prompt_first"]
        else { throw OpenMedDecisionError.invalidConfiguration(reason: "fixture") }
        return try OpenMedGLiClassConfiguration(
            prompt: settings["prompt"] == .null ? nil : string(settings["prompt"]), examples: examples,
            scoreLevels: array(settings["score_levels"]).map { try string($0) }, promptFirst: promptFirst,
            maxLength: Int(maxLength))
    }

    private func policy(_ value: AgentJSON?) throws -> OpenMedDecisionAccessPolicy {
        guard let value, value != .null else { return .standard }
        let fields = try object(value)
        let strings = { (key: String) in Set(try self.array(fields[key]).map { try self.string($0) }) }
        return try OpenMedDecisionAccessPolicy(
            allowedNamespaces: strings("allowed_namespaces"), allowedPurposes: strings("allowed_purposes"),
            allowedBackendKinds: strings("allowed_backend_kinds"), policyVersion: string(fields["policy_version"]))
    }

    private func profiles(_ value: AgentJSON?) throws -> [OpenMedDecisionCalibrationProfile] {
        guard let value, value != .null else { return [.standard] }
        return try array(value).map { try OpenMedDecisionCalibrationProfile(json: $0.canonical()) }
    }

    private func assertClose(_ actual: AgentJSON, _ expected: AgentJSON, tolerance: Double, path: String) {
        switch (actual, expected) {
        case (.object(let lhs), .object(let rhs)):
            XCTAssertEqual(Set(lhs.keys), Set(rhs.keys), path)
            for (key, value) in rhs where lhs[key] != nil {
                assertClose(lhs[key]!, value, tolerance: tolerance, path: path + "." + key)
            }
        case (.array(let lhs), .array(let rhs)):
            XCTAssertEqual(lhs.count, rhs.count, path)
            for (index, pair) in zip(lhs, rhs).enumerated() {
                assertClose(pair.0, pair.1, tolerance: tolerance, path: "\(path)[\(index)]")
            }
        default:
            if let lhs = actual.decisionNumber, let rhs = expected.decisionNumber {
                XCTAssertEqual(lhs, rhs, accuracy: tolerance, path)
            } else {
                XCTAssertEqual(actual, expected, path)
            }
        }
    }
}

/// The fixture's word-level tokenizer: control markers, ASCII lowercasing and
/// one word pattern, framed by `[CLS]` and `[SEP]`.
private struct WordLevelTokenizer: OpenMedDecisionTokenizer {
    let ids: [String: Int]
    let markers: [String]
    let pattern: NSRegularExpression
    let unknown: Int
    let classification: Int
    let separator: Int

    init(_ value: AgentJSON?) throws {
        guard case .object(let spec)? = value, case .array(let vocab)? = spec["vocab"],
            case .array(let markerValues)? = spec["markers"], case .string(let regex)? = spec["word_pattern"],
            case .string(let unk)? = spec["unk_token"], case .string(let cls)? = spec["cls_token"],
            case .string(let sep)? = spec["sep_token"]
        else { throw OpenMedDecisionError.invalidConfiguration(reason: "fixture") }
        var ids: [String: Int] = [:]
        for (index, token) in vocab.enumerated() {
            if case .string(let text) = token { ids[text] = index }
        }
        self.ids = ids
        markers = markerValues.compactMap { if case .string(let text) = $0 { return text } else { return nil } }
        pattern = try NSRegularExpression(pattern: regex)
        unknown = ids[unk] ?? 1
        classification = ids[cls] ?? 2
        separator = ids[sep] ?? 3
    }

    func tokenID(for token: String) -> Int? { ids[token] }

    func encode(_ text: String) throws -> [Int] {
        var result = [classification]
        var rest = Substring(text)
        while true {
            let next = markers.compactMap { marker in rest.range(of: marker).map { ($0, marker) } }
                .min { $0.0.lowerBound < $1.0.lowerBound }
            appendWords(String(next.map { rest[..<$0.0.lowerBound] } ?? rest), to: &result)
            guard let next else { break }
            result.append(ids[next.1] ?? unknown)
            rest = rest[next.0.upperBound...]
        }
        result.append(separator)
        return result
    }

    private func appendWords(_ piece: String, to result: inout [Int]) {
        var scalars = String.UnicodeScalarView()
        for scalar in piece.unicodeScalars {
            scalars.append((65...90).contains(scalar.value) ? Unicode.Scalar(scalar.value + 32)! : scalar)
        }
        let lowered = String(scalars)
        let range = NSRange(lowered.startIndex..., in: lowered)
        for match in pattern.matches(in: lowered, range: range) {
            if let span = Range(match.range, in: lowered) { result.append(ids[String(lowered[span])] ?? unknown) }
        }
    }
}

/// The fixture's tiny GLiClass-style encoder, in Float64 with float32 output.
private struct TinyEncoderSpec {
    let embeddings: [[Double]]
    let projection: [[Double]]
    let bias: [Double]
    let size: Int
    let scale: Double
    let logitBias: Double
    let labelID: Int
    let separatorID: Int
    let ignored: Set<Int>

    init(_ value: AgentJSON?) throws {
        let bad = OpenMedDecisionError.invalidConfiguration(reason: "fixture")
        guard case .object(let spec)? = value else { throw bad }
        func numbers(_ value: AgentJSON?) throws -> [Double] {
            guard case .array(let items)? = value else { throw bad }
            return try items.map {
                guard let number = $0.decisionNumber else { throw bad }
                return number
            }
        }
        func matrix(_ value: AgentJSON?) throws -> [[Double]] {
            guard case .array(let rows)? = value else { throw bad }
            return try rows.map { try numbers($0) }
        }
        func integer(_ value: AgentJSON?) throws -> Int {
            guard case .integer(let number)? = value else { throw bad }
            return Int(number)
        }
        embeddings = try matrix(spec["embeddings"])
        projection = try matrix(spec["projection"])
        bias = try numbers(spec["projection_bias"])
        size = try integer(spec["hidden_size"])
        scale = try XCTUnwrap(spec["logit_scale"]?.decisionNumber)
        logitBias = try XCTUnwrap(spec["logit_bias"]?.decisionNumber)
        labelID = try integer(spec["label_token_id"])
        separatorID = try integer(spec["separator_token_id"])
        ignored = Set(try numbers(spec["ignored_token_ids"]).map { Int($0) })
    }

    func logits(ids: [Int], mask: [Int]) -> [Double] {
        let hidden = ids.map { token -> [Double] in
            (0..<size).map { column in
                var total = 0.0
                for inner in 0..<size { total += embeddings[token][inner] * projection[inner][column] }
                return tanh(total + bias[column])
            }
        }
        var spans: [Range<Int>] = []
        for position in ids.indices where mask[position] == 1 && ids[position] == labelID {
            var end = position + 1
            while end < ids.count && ids[end] != labelID && ids[end] != separatorID { end += 1 }
            spans.append(position..<end)
        }
        let inLabel = Set(spans.flatMap { Array($0) })
        let context = ids.indices.filter { mask[$0] == 1 && !inLabel.contains($0) && !ignored.contains(ids[$0]) }
        func mean(_ positions: [Int]) -> [Double] {
            var totals = Array(repeating: 0.0, count: size)
            for position in positions {
                for column in 0..<size { totals[column] += hidden[position][column] }
            }
            return positions.isEmpty ? totals : totals.map { $0 / Double(positions.count) }
        }
        let text = mean(context)
        return spans.map { span in
            let label = mean(span.filter { mask[$0] == 1 })
            var dot = 0.0
            for column in 0..<size { dot += label[column] * text[column] }
            return scale * dot + logitBias
        }
    }
}

/// A Core ML-shaped model that runs the tiny encoder and returns float32 logits.
private final class TinyCoreMLModel: OpenMedDecisionFeaturePredicting {
    struct Call {
        let ids: [Int]
        let logits: [Double]?
    }

    struct SyntheticFault: Error {}

    let spec: TinyEncoderSpec
    let fault: String?
    private(set) var calls: [Call] = []

    init(spec: TinyEncoderSpec, fault: String?) {
        self.spec = spec
        self.fault = fault
    }

    func prediction(from input: MLFeatureProvider) throws -> MLFeatureProvider {
        let ids = try XCTUnwrap(input.featureValue(for: "input_ids")?.multiArrayValue)
        let mask = try XCTUnwrap(input.featureValue(for: "attention_mask")?.multiArrayValue)
        XCTAssertEqual(ids.dataType, .int32)
        XCTAssertEqual(ids.shape, mask.shape)
        let count = ids.shape[1].intValue
        let tokens = (0..<count).map { ids[[0, NSNumber(value: $0)]].intValue }
        let attention = (0..<count).map { mask[[0, NSNumber(value: $0)]].intValue }
        if fault == "raise" {
            calls.append(Call(ids: tokens, logits: nil))
            throw SyntheticFault()
        }
        var logits = spec.logits(ids: tokens, mask: attention).map { Double(Float($0)) }
        if fault == "short" { logits.removeLast() }
        if fault == "non_finite" { logits[0] = .nan }
        calls.append(Call(ids: tokens, logits: fault == "non_finite" ? nil : logits))
        let shape: [NSNumber] = fault == "rank3" ? [1, 1, NSNumber(value: logits.count)] : [1, NSNumber(value: logits.count)]
        let output = try MLMultiArray(shape: shape, dataType: .float32)
        for (index, value) in logits.enumerated() {
            output[fault == "rank3" ? [0, 0, NSNumber(value: index)] : [0, NSNumber(value: index)]] = NSNumber(value: Float(value))
        }
        return try MLDictionaryFeatureProvider(dictionary: ["logits": MLFeatureValue(multiArray: output)])
    }
}
